// The app sends the whole last day each time, so only the newest is kept.
const body = $input.first().json.body || {};
if (!body.as_of || !Array.isArray(body.accounts)) {
  throw new Error('Not a trail: as_of and accounts are required');
}
$getWorkflowStaticData('global').trail = {
  as_of: body.as_of,
  accounts: body.accounts,
  unreadable: Array.isArray(body.unreadable) ? body.unreadable : [],
};
return [{ json: { ok: true } }];

// Briefing plugin: the APP section. What each account did, as the app last told it.
// Contract: 05_daily-briefing/docs/briefing-plugin-spec.md
//
// PLAIN TEXT ONLY, never HTML. The briefing escapes centrally.
const MAX_ACCOUNTS = 8;
const MAX_ROWS = 6;        // per account; the newest are kept
const STALE_AFTER_H = 2;   // the app tells every half hour

const tz = $('When Called for Briefing').first().json.tz || 'UTC';
const told = $getWorkflowStaticData('global').trail;
const section = (blocks, empty) => [{ json: { key: 'app', icon: '🏺', title: 'APP', blocks, empty } }];
// Always exactly one item: zero items is indistinguishable from a crash.
if (!told) return section([], 'The app has not told anything yet');

const clock = (ms, withDay) => new Date(ms).toLocaleString('en-GB', {
  ...(withDay ? { day: '2-digit', month: 'short' } : {}),
  hour: '2-digit', minute: '2-digit', hour12: false, timeZone: tz,
});
// A row is "YYYY-MM-DD HH:MM:SS what subject", in UTC.
const line = (row) => {
  const text = String(row ?? '');
  const at = Date.parse(text.slice(0, 10) + 'T' + text.slice(11, 19) + 'Z');
  return Number.isFinite(at) ? clock(at) + ' ' + text.slice(20) : text;
};

const blocks = [];
const age = Date.now() - Date.parse(told.as_of);
if (!(age < STALE_AFTER_H * 3600e3)) {
  blocks.push({ heading: 'Stale', items: ['Last told ' + (Number.isFinite(age) ? clock(Date.now() - age, true) : 'at an unreadable time')] });
}
const accounts = told.accounts.filter((a) => a && Array.isArray(a.rows) && a.rows.length);
for (const a of accounts.slice(0, MAX_ACCOUNTS)) {
  const items = a.rows.slice(-MAX_ROWS).map(line);
  if (a.rows.length > MAX_ROWS) items.unshift('+' + (a.rows.length - MAX_ROWS) + ' earlier');
  blocks.push({ heading: String(a.who || '?'), items });
}
if (accounts.length > MAX_ACCOUNTS) {
  blocks.push({ heading: 'More', items: accounts.slice(MAX_ACCOUNTS).map((a) => String(a.who || '?') + ' · ' + a.rows.length) });
}
if (told.unreadable.length) blocks.push({ heading: 'Could not read', items: told.unreadable.map(String) });

return section(blocks, 'Nobody did anything');
